pub(crate) fn check_not_pure_because(contract: &FnContract) -> Option<&'static str> {
    if !contract.sync_claim.is_sync() { return Some("can pause"); }
    if !contract.fails_with.is_empty() { return Some("can fail"); }
    if contract.mutates { return Some("changes what it is called on"); }
    if !contract.touches_known || !contract.touches.is_empty() { return Some("touches something outside the program's values"); }
    if contract.touches_a_lock.holds() { return Some("takes a lock"); }
    None
}

